import { Field, FieldError, FieldLabel } from "@/registry/erbium/ui/field";
import { PasswordInput } from "@/registry/erbium/ui/password-input";

const PasswordInputInvalid = () => (
  <Field invalid className="max-w-sm">
    <FieldLabel>Password</FieldLabel>
    <PasswordInput defaultValue="short" />
    <FieldError match>Use at least 8 characters.</FieldError>
  </Field>
);

export default PasswordInputInvalid;

import PasswordInputInvalid from "../examples/password-input-invalid";

const Example = () => <PasswordInputInvalid />;

export default Example;
